text/plain.example:
{
  "data": {
    "purchase_order": {
      "label": "Purchase Order",
      "events": [
        {
          "key": "submitted",
          "label": "PO Submitted",
          "trigger": "automatic",
          "description": "Sends automatically to the supplier every time a purchase order is submitted."
        },
        {
          "key": "updated",
          "label": "PO Updated",
          "trigger": "automatic",
          "description": "Sends automatically every time a submitted purchase order is changed."
        },
        {
          "key": "manual",
          "label": "Manual Send",
          "trigger": "manual",
          "description": "Never sends on its own. You choose this template from the purchase order screen when you want to email the supplier."
        }
      ],
      "variables": [
        {
          "token": "{{purchase_order_number}}",
          "label": "Purchase Order ID",
          "group": "Details",
          "is_table": false
        },
        {
          "token": "{{purchase_order_lines}}",
          "label": "Order Item List",
          "group": "Line Items",
          "is_table": true
        }
      ],
      "documents": [
        {
          "key": "po_pdf",
          "label": "PO PDF",
          "mime": "application/pdf"
        },
        {
          "key": "po_csv",
          "label": "PO CSV",
          "mime": "text/csv"
        },
        {
          "key": "po_xlsx",
          "label": "PO XLSX",
          "mime": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
        }
      ]
    }
  }
}
